// Turn the ledger event into a subject + plain-text message.
const { event, data } = $('Ledger webhook').first().json.body;
const money = (v) => v === null || v === undefined ? '—' : `${data.currency ?? ''} ${Number(v).toLocaleString('en-GB', { maximumFractionDigits: 0 })}`;
let subject;
let text;
if (event === 'deployment.flag_changed') {
  subject = data.test ? 'Test alert from AI ROI Ledger' : `${data.name}: flag changed ${data.previous_flag} → ${data.flag}`;
  text = data.test ? data.message : [
    `${data.name} is now flagged ${data.flag.toUpperCase()} (was ${data.previous_flag}).`,
    ...(data.reasons ?? []).map((r) => `• ${r}`),
    `Net to date: ${money(data.net)} · ROI: ${data.roi === null ? '—' : Math.round(data.roi * 100) + '%'} · Confidence: ${data.confidence}`,
  ].join('\n');
} else if (event === 'deployment.cost_per_run_spike') {
  subject = `${data.name}: cost per run up ${data.change_pct}% week on week`;
  text = `Cost per completed run rose from ${money(data.cost_per_run_last_week)} to ${money(data.cost_per_run_this_week)} (alert threshold ${data.threshold_pct}%).`;
} else if (event === 'snapshot.monthly_summary') {
  subject = `AI ROI summary for ${data.month}`;
  text = [
    `Totals to date: cost ${money(data.totals.cost_total)}, value ${money(data.totals.value_total)}, net ${money(data.totals.net)}.`,
    '',
    ...data.deployments.map((d) => `${d.name}: net ${money(d.net)}, flag ${d.flag}, payback ${d.payback_date ?? '—'}${d.payback_projected ? ' (projected)' : ''}, confidence ${d.confidence}`),
  ].join('\n');
} else {
  subject = `AI ROI Ledger: ${event}`;
  text = JSON.stringify(data, null, 2);
}
return [{ json: { event, subject, text } }];
